package main
import("bytes";"fmt";"strings";"time";"os";"io";"context"; astits "github.com/asticode/go-astits"; astisub "github.com/asticode/go-astisub")
func must(v bool){if !v{panic("baseline observation mismatch")}}
func main(){s,e:=astisub.ReadFromWebVTT(strings.NewReader("WEBVTT\n\n00:00:01.000 --> 00:00:03.000\nHello\n\n"));if e!=nil{panic(e)};s.Add(time.Second);s.Fragment(time.Second);must(len(s.Items)==2);must(s.Items[0].StartAt==2*time.Second);must(s.Items[1].EndAt==4*time.Second);var b bytes.Buffer;if e=s.WriteToSRT(&b);e!=nil{panic(e)};r,e:=astisub.ReadFromSRT(&b);if e!=nil{panic(e)};must(len(r.Items)==2&&r.Items[0].String()=="Hello"&&r.Items[1].EndAt==4*time.Second);f,e:=os.Open("task_support/fixtures/basic.ts");if e!=nil{panic(e)};defer f.Close();d:=astits.NewDemuxer(context.Background(),f);n:=0;for{v,e:=d.NextData();if e==astits.ErrNoMorePackets||e==io.EOF{break};if e!=nil{panic(e)};if v.PES==nil{continue};must(v.PID==256&&v.PES.Header.StreamID==astits.StreamIDPrivateStream1);want,e:=os.ReadFile(fmt.Sprintf("task_support/fixtures/pes%d.bin",n));if e!=nil{panic(e)};must(bytes.Equal(want,v.PES.Data));must(v.PES.Header.OptionalHeader.PTS.Base==[]int64{90000,90000,270000,360000}[n]);n++};must(n==4);fmt.Println("DVB_STARTING_BASELINE_OK fragments=2 srt_roundtrip=1 transport_pes=4")}
